# name: outlier_tolerant_rule_yes
# description: Among 3-4-example sets where no rule of size <=25 (multiples of 3-50, ends-in-digit, squares, powers of 2/3) fits all examples but one fits all but one, yes rate for non-example targets in that smallest leave-one-out rule; observed above the null means people discount a single outlier example and still follow the rule more than the model's random-example noise allows (below = they abandon the rule more readily).
def test_statistic(df):
    rules = [set(range(m, 101, m)) for m in range(4, 51)]
    rules += [set(range(d if d else 10, 101, 10)) for d in range(10)]
    rules += [{n * n for n in range(1, 11)}, {2, 4, 8, 16, 32, 64}, {3, 9, 27, 81}]
    rules = [r for r in rules if len(r) <= 25]
    rules.sort(key=len)
    sets = df["number_set"].astype(str)
    info = {}
    for s in sets.unique():
        ex = [int(x) for x in s.split(",")]
        best = None
        if len(ex) >= 3 and not any(all(x in r for x in ex) for r in rules):
            for r in rules:
                if sum(x in r for x in ex) == len(ex) - 1:
                    best = r
                    break
        info[s] = (best, set(ex))
    t = df["target"].astype(int).to_numpy()
    m = np.array([info[s][0] is not None and tt in info[s][0] and tt not in info[s][1]
                  for s, tt in zip(sets, t)])
    if m.sum() == 0:
        return 0.0
    return float(df["rating"].to_numpy()[m].mean())

# name: small_vs_large_absolute_far_target
# description: For targets more than 15 away from every example, yes rate for targets 1-20 minus targets 81-100 (absolute magnitude, not relative to examples); observed above the null means people favour small numbers as generic program outputs beyond what the model's concepts and uniform noise produce (below = favour large numbers).
def test_statistic(df):
    sets = df["number_set"].astype(str)
    ex = {s: np.array([int(x) for x in s.split(",")]) for s in sets.unique()}
    t = df["target"].astype(int).to_numpy()
    dist = np.array([np.abs(ex[s] - tt).min() for s, tt in zip(sets, t)])
    ok = dist > 15
    a, b = ok & (t <= 20), ok & (t >= 81)
    y = df["rating"].to_numpy().astype(float)
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(y[a].mean() - y[b].mean())

# name: nonzero_residue_class_contrast
# description: Among 2+-example sets whose examples all share a nonzero residue r mod k for some k in {3,4,6,7,8,9,11,12} (largest such k; e.g. odd multiples of 3 = 3 mod 6), yes rate for non-example targets with the same residue minus targets with a different residue; observed above the null means people infer offset/intersection concepts ("odd multiples of 3") the model's zero-residue multiples rules lack (below = less than the model).
def test_statistic(df):
    sets = df["number_set"].astype(str)
    info = {}
    for s in sets.unique():
        ex = [int(x) for x in s.split(",")]
        kk, rr = 0, -1
        if len(ex) >= 2:
            for k in [12, 11, 9, 8, 7, 6, 4, 3]:
                res = {x % k for x in ex}
                if len(res) == 1 and list(res)[0] != 0:
                    kk, rr = k, list(res)[0]
                    break
        info[s] = (kk, rr, ",".join(str(x) for x in ex))
    k = sets.map(lambda s: info[s][0]).to_numpy()
    r = sets.map(lambda s: info[s][1]).to_numpy()
    t = df["target"].astype(int).to_numpy()
    inset = np.array([str(tt) in s.split(",") for tt, s in zip(t, sets)])
    ok = (k > 0) & ~inset
    if ok.sum() == 0:
        return 0.0
    same = ok & (t % np.maximum(k, 1) == r)
    diff = ok & ~same
    y = df["rating"].to_numpy().astype(float)
    if same.sum() == 0 or diff.sum() == 0:
        return 0.0
    return float(y[same].mean() - y[diff].mean())
